"""Pinned local FIA legacy/optimized correctness and timing comparison."""
import base64
import gzip
import json
from pathlib import Path
import subprocess
import sys
import tempfile

PAYLOAD = ''

if __name__ == "__main__":
    with tempfile.TemporaryDirectory(prefix="fia-optimized-") as folder:
        root = Path(folder)
        for name, content in json.loads(gzip.decompress(base64.b64decode(PAYLOAD))).items():
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
        raise SystemExit(subprocess.call([sys.executable, "-u", str(root / 'tests/e2e/nightly/single_node/ops/singlecard_ops/check_kimi_k3_qfm_fia_prefill.py'), *sys.argv[1:]]))
